const r = await tools.exec_command({cmd:"python - <<'PY'
import json,os, pathlib, hashlib, stat
m=json.load(open(os.environ['STAMPED_DELIVERY_MANIFEST'])); root=pathlib.Path(os.environ['STAMPED_JUDGE_TARGET']); bad=[]; miss=[]; checked=0
for e in m['entries']:
 p=root/e['path'].removeprefix('content/workspace/') if e['path'].startswith('content/workspace/') else root/e['path']
 if e['kind']=='directory':
  if not p.is_dir(): miss.append((str(p),'directory'))
 elif e['kind']=='file':
  if not p.exists(): miss.append((str(p),'file')); continue
  # symlinks are captured as bytes if destination is materialized, verify bytes if possible
  if p.is_file() and 'sha256' in e:
   h=hashlib.sha256(p.read_bytes()).hexdigest()
   checked+=1
   if h!=e['sha256']: bad.append((str(p),e['sha256'],h))
print('capture_status',m['capture_status'],'errors',m.get('errors'),'omissions',m.get('omissions'))
print('file hashes checked',checked,'mismatches',len(bad),'missing',len(miss))
print('mismatch examples',bad[:10]); print('missing examples',miss[:10])
print('target entries',len(list(root.iterdir())))
PY
ls -l "$STAMPED_JUDGE_TARGET/input/data/sub-001_hypo1_cope.nii.gz"; rg -n 'entry|outputs|python|pip|pixi|requirements|nilearn' "$STAMPED_JUDGE_TARGET" -g '*.md' -g '*.toml' -g '*.yml' -g '*.yaml' -g '*.txt' -g '*.sh' -g '*.json' -g '!input/sources.json' -g '!*.nii.gz' | head -100
cat "$STAMPED_WORKER_STOP_RECEIPT" | python -c 'import json,sys; d=json.load(sys.stdin); print(json.dumps({k:v for k,v in d.items() if k not in ("declared_artifacts",)},indent=2)); print("artifacts",[(x.get("path"),x.get("kind"),x.get("declaration")) for x in d.get("declared_artifacts",[])])'","yield_time_ms":10000,"max_output_tokens":5000});
text(r.output)

